        return os.get_terminal_size().columns
    except OSError:
        return 80

def is_binary(data):
    if not data:
        return False
    return b'\x00' in data[:4096]

def parse_line_range(range_str, total_lines):
    # This is a simplified version of line range parsing
    try:
        if ':' not in range_str:
            return [int(range_str)]
        parts = range_str.split(':')
        if len(parts) == 2:
            start_str, end_str = parts
            start = int(start_str) if start_str else 1
            if start < 0: start = max(1, total_lines + start + 1)
            end = int(end_str) if end_str else total_lines
            return list(range(start, end + 1))
        elif len(parts) == 3:
            # Handle 35::5 or 30:40:2
            p1, p2, p3 = parts
            if p2 == '': # 35::5
                center = int(p1)
                context = int(p3)
                return list(range(max(1, center - context), min(total_lines, center + context) + 1))
            else: # 30:40:2
                start = int(p1)
                end = int(p2)
                context = int(p3)
                return list(range(max(1, start - context), min(total_lines, end + context) + 1))
